// Optional injected local storage capability. No background probes or saves.
export function attachNativeBackup({host,nativeStore,model,snapshot,replace,getRevision,signal}){
 const doc=host.ownerDocument;let disposed=false,busy=false;const control=new AbortController();
 host.innerHTML='<h2>Native workspace backup</h2><p data-native-status role="status"></p><button type="button" data-native-save>Save all rooms to native storage</button><button type="button" data-native-load>Restore all rooms from native storage</button><p>Restore replaces the current workspace; Undo restores your previous session state. Storage is optional; browser-only authoring remains available.</p><button type="button" data-native-history>List native recovery revisions</button><select aria-label="Recovery revision" data-native-revisions></select><button type="button" data-native-recover>Restore selected revision to native storage and workspace</button><p>Recovery replaces native and browser workspace only after checking for conflicts. Export unsaved edits first. Undo restores browser state only, not the native backup.</p>';
 const one=q=>host.querySelector(q),status=one('[data-native-status]'),save=one('[data-native-save]'),load=one('[data-native-load]'),history=one('[data-native-history]'),choices=one('[data-native-revisions]'),recover=one('[data-native-recover]');let listed=[];
 const available=typeof nativeStore?.save==='function'&&typeof nativeStore?.load==='function';
 const historyAvailable=typeof nativeStore?.revisions==='function'&&typeof nativeStore?.readRevision==='function'&&typeof nativeStore?.restoreRevision==='function';
 function enabled(){save.disabled=load.disabled=busy||!available;history.disabled=busy||!historyAvailable;recover.disabled=choices.disabled=busy||!historyAvailable||listed.length===0;}
 status.textContent=available?'Local native storage available. No action performed.':'Not connected. Browser storage and file backups still work.';enabled();
 async function run(action){if(disposed||busy||!available)return;busy=true;enabled();const revision=getRevision();try{
  if(action==='history'){const rows=await nativeStore.revisions({signal:control.signal});if(disposed)return;listed=rows;choices.replaceChildren();for(const row of rows){const option=doc.createElement('option');option.value=String(row.id);option.textContent=`Revision ${row.id}: ${row.event}${row.source_revision?' from '+row.source_revision:''}`;choices.append(option);}status.textContent=rows.length?'Select a revision to recover. Existing workspace has not changed.':'No recovery revisions retained.';}
  else if(action==='recover'){model.encodeWorkspace(snapshot());const id=Number(choices.value);if(!listed.some(v=>v.id===id))throw Error('Select a listed revision');const text=await nativeStore.readRevision(id,{signal:control.signal});if(disposed)return;const value=model.parseWorkspace(text);if(getRevision()!==revision){status.textContent='Workspace changed while reading revision. Recovery not applied.';return;}const committed=await nativeStore.restoreRevision(id,{signal:control.signal});if(disposed)return;const restored=model.parseWorkspace(committed);if(getRevision()!==revision){status.textContent='Selected revision saved to native storage. Newer browser edits were retained; restore explicitly when ready.';return;}replace(restored);status.textContent=`Revision ${id} recovered to native storage and workspace. Browser Undo is available.`;}
  else if(action==='save'){const text=model.encodeWorkspace(snapshot());await nativeStore.save(text,{signal:control.signal});if(!disposed)status.textContent=getRevision()===revision?'Captured workspace saved to native SQLite.':'Captured workspace saved. Newer browser edits are not yet saved to native storage.';}
  else {const text=await nativeStore.load({signal:control.signal});if(disposed)return;if(text===null){nativeStore.acceptLoad?.(text);status.textContent='No native backup exists. Current workspace unchanged.';return;}const value=model.parseWorkspace(text);if(getRevision()!==revision){status.textContent='Workspace changed while loading. Restore not applied; retry when ready.';return;}replace(value);nativeStore.acceptLoad?.(text);status.textContent='Native backup restored into this workspace. Undo is available.';}
 }catch(e){if(!disposed)status.textContent=e.code==='NATIVE_CONFLICT'?`Save conflict: ${e.message}. Current browser edits were not replaced.`:`Native ${action} failed: ${e.message}. Review the current workspace; Undo may be available.`;}finally{busy=false;if(!disposed)enabled();}}
 save.addEventListener('click',()=>run('save'));load.addEventListener('click',()=>run('load'));history.addEventListener('click',()=>run('history'));recover.addEventListener('click',()=>run('recover'));
 function dispose(){if(disposed)return;disposed=true;control.abort();signal?.removeEventListener('abort',dispose);host.replaceChildren();}
 signal?.addEventListener('abort',dispose,{once:true});if(signal?.aborted)dispose();return {dispose};
}
